{
  "domain": "Spanish A2 feelings",
  "description": "Spanish at A2 for talking about feelings: saying how you feel, asking, and reacting (Latin American Spanish, broadly neutral).",
  "terms": [
    {
      "term": "estar + adjetivo",
      "category": "Pattern",
      "definition": "Says how you feel right now. The feeling word matches you: cansado for a man, cansada for a woman.",
      "example": "Hoy estoy cansada y un poco triste. — I'm tired and a bit sad today.",
      "anti_example": "Not 'soy cansado' for 'I'm tired': feelings right now take estar, so 'estoy cansado'."
    },
    {
      "term": "¿Qué te pasa?",
      "category": "Phrase",
      "definition": "Asks a friend what's wrong when they look upset or quiet.",
      "example": "Estás muy serio hoy. ¿Qué te pasa? — You look very serious today. What's wrong?",
      "discussion": "Say '¿Qué le pasa?' to someone you call usted. Answers often start with 'Nada' or 'Es que…'."
    },
    {
      "term": "sentirse",
      "category": "Verb",
      "definition": "Describes how your body or mood feels, often with bien, mal or cansado. You always need me, te or se: 'me siento'.",
      "example": "No me siento bien, hoy no voy a la oficina.",
      "anti_example": "Not 'siento triste' for 'I feel sad': with a feeling word you need me, so 'me siento triste'."
    },
    {
      "term": "preocupado",
      "category": "Adjective",
      "definition": "Worried about something that may go wrong, like work, money or a sick relative.",
      "example": "Mi hijo tiene fiebre y estoy muy preocupada.",
      "discussion": "Use estar, and por for the cause: 'estoy preocupado por el examen'. A woman says preocupada."
    },
    {
      "term": "me molesta",
      "category": "Verb",
      "definition": "Tells people that something bothers you. It works like 'me gusta': the annoying thing does the verb.",
      "example": "Me molesta el ruido de la calle por la noche.",
      "anti_example": "Not 'yo molesto el ruido': that says you bother the noise. Say 'me molesta el ruido'."
    },
    {
      "term": "enojado",
      "category": "Adjective",
      "definition": "Angry at someone or something, from annoyed to really mad.",
      "example": "Mi jefe está enojado porque llegué tarde. — My boss is angry because I was late.",
      "discussion": "Latin America says enojado; Spain says enfadado. Add con for the person: 'estoy enojado con mi hermano'."
    },
    {
      "term": "tener miedo",
      "category": "Pattern",
      "definition": "Being afraid, said with tener because in Spanish you 'have fear'. Add de for what scares you.",
      "example": "Mi hija tiene miedo de los perros grandes.",
      "anti_example": "Not 'estoy miedo' for 'I'm afraid': fear is something you have, so 'tengo miedo'."
    },
    {
      "term": "me alegro",
      "category": "Phrase",
      "definition": "Your warm reply to good news, like 'I'm glad' or 'good for you'.",
      "example": "¿Te dieron el trabajo? ¡Me alegro mucho! — You got the job? I'm so glad!",
      "discussion": "Say '¡Me alegro por ti!' to make it about the other person. Very common with friends and coworkers."
    },
    {
      "term": "aburrido",
      "category": "Adjective",
      "definition": "Bored, with estar: nothing to do and time goes slowly.",
      "example": "Estoy aburrido, no hay nada en la tele. — I'm bored, there's nothing on TV.",
      "anti_example": "Not 'soy aburrido' for 'I'm bored': that means 'I'm boring'. Say 'estoy aburrido'."
    },
    {
      "term": "¡Qué lástima!",
      "category": "Phrase",
      "definition": "Shows you feel sorry when someone shares bad news, like 'what a shame' or 'too bad'.",
      "example": "¿No vienes a la fiesta? ¡Qué lástima!",
      "discussion": "Fine for small letdowns. For a death or a serious illness, say 'lo siento mucho' instead."
    }
